  1 | import { useCallback, useMemo, useRef, useState } from "react";
  2 | import type { Track } from "../types";
  3 | 
  4 | interface PlaylistProps {
  5 |   tracks: Track[];
  6 |   currentTrackId: string | null;
  7 |   isPlaying: boolean;
  8 |   onSelectTrack: (track: Track) => void;
  9 |   onReorderPlaylist?: (tracks: Track[]) => void;
 10 |   onDropFiles?: (files: FileList) => void;
 11 | }
 12 | 
 13 | function formatDuration(seconds: number): string {
 14 |   const mins = Math.floor(seconds / 60);
 15 |   const secs = Math.floor(seconds % 60);
 16 |   return `${mins}:${secs.toString().padStart(2, "0")}`;
 17 | }
 18 | 
 19 | function normalizeText(text: string): string {
 20 |   return text
 21 |     .normalize("NFD")
 22 |     .replace(/[\u0300-\u036f]/g, "")
 23 |     .toLowerCase();
 24 | }
 25 | 
 26 | export function Playlist({
 27 |   tracks,
 28 |   currentTrackId,
 29 |   isPlaying,
 30 |   onSelectTrack,
 31 |   onReorderPlaylist,
 32 |   onDropFiles,
 33 | }: PlaylistProps) {
 34 |   const [dragOverIndex, setDragOverIndex] = useState<number | null>(null);
 35 |   const dragItemIndex = useRef<number | null>(null);
 36 |   const [isDragOver, setIsDragOver] = useState(false);
 37 |   const [searchQuery, setSearchQuery] = useState("");
 38 | 
 39 |   // Filtro de busca
 40 |   const normalizedQuery = normalizeText(searchQuery);
 41 | 
 42 |   const filteredTracks = useMemo(() => {
 43 |     if (!normalizedQuery) return tracks;
 44 |     return tracks.filter((track) => {
 45 |       const title = normalizeText(track.title);
 46 |       const artist = track.artist ? normalizeText(track.artist) : "";
 47 |       return title.includes(normalizedQuery) || artist.includes(normalizedQuery);
 48 |     });
 49 |   }, [tracks, normalizedQuery]);
 50 | 
 51 |   // Mapeia índice filtrado → índice original para drag & drop
 52 |   const filteredToOriginalIndex = useMemo(() => {
 53 |     if (!normalizedQuery) return null;
 54 |     return filteredTracks.map((ft) => tracks.indexOf(ft));
 55 |   }, [filteredTracks, tracks, normalizedQuery]);
 56 | 
 57 |   // Drag & drop de arquivos do sistema
 58 |   const handleDragOverWindow = useCallback((e: React.DragEvent) => {
 59 |     if (e.dataTransfer.types.includes("Files")) {
 60 |       e.preventDefault();
 61 |       e.stopPropagation();
 62 |       setIsDragOver(true);
 63 |     }
 64 |   }, []);
 65 | 
 66 |   const handleDragLeaveWindow = useCallback((e: React.DragEvent) => {
 67 |     e.preventDefault();
 68 |     setIsDragOver(false);
 69 |   }, []);
 70 | 
 71 |   const handleDropWindow = useCallback(
 72 |     (e: React.DragEvent) => {
 73 |       e.preventDefault();
 74 |       e.stopPropagation();
 75 |       setIsDragOver(false);
 76 | 
 77 |       if (e.dataTransfer.files && e.dataTransfer.files.length > 0) {
 78 |         onDropFiles?.(e.dataTransfer.files);
 79 |       }
 80 |     },
 81 |     [onDropFiles]
 82 |   );
 83 | 
 84 |   const resolveOriginalIndex = useCallback(
 85 |     (filteredIndex: number): number => {
 86 |       if (filteredToOriginalIndex) {
 87 |         return filteredToOriginalIndex[filteredIndex];
 88 |       }
 89 |       return filteredIndex;
 90 |     },
 91 |     [filteredToOriginalIndex]
 92 |   );
 93 | 
 94 |   const handleDragStart = useCallback(
 95 |     (e: React.DragEvent<HTMLLIElement>, filteredIndex: number) => {
 96 |       const originalIndex = resolveOriginalIndex(filteredIndex);
 97 |       dragItemIndex.current = originalIndex;
 98 |       e.dataTransfer.effectAllowed = "move";
 99 |       e.dataTransfer.setData("text/plain", String(originalIndex));
100 |       // Add a slight delay so the drag image shows properly
101 |       e.currentTarget.classList.add("dragging");
102 |     },
103 |     [resolveOriginalIndex]
104 |   );
105 | 
106 |   const handleDragEnd = useCallback(
107 |     (e: React.DragEvent<HTMLLIElement>) => {
108 |       e.currentTarget.classList.remove("dragging");
109 |       dragItemIndex.current = null;
110 |       setDragOverIndex(null);
111 |     },
112 |     []
113 |   );
114 | 
115 |   const handleDragOver = useCallback(
116 |     (e: React.DragEvent<HTMLLIElement>, filteredIndex: number) => {
117 |       e.preventDefault();
118 |       e.dataTransfer.dropEffect = "move";
119 |       setDragOverIndex(filteredIndex);
120 |     },
121 |     []
122 |   );
123 | 
124 |   const handleDragLeave = useCallback(() => {
125 |     setDragOverIndex(null);
126 |   }, []);
127 | 
128 |   const handleDrop = useCallback(
129 |     (e: React.DragEvent<HTMLLIElement>, dropFilteredIndex: number) => {
130 |       e.preventDefault();
131 |       const fromIndex = dragItemIndex.current;
132 |       const dropIndex = resolveOriginalIndex(dropFilteredIndex);
133 |       if (fromIndex === null || fromIndex === dropIndex) {
134 |         setDragOverIndex(null);
135 |         return;
136 |       }
137 | 
138 |       const reordered = [...tracks];
139 |       const [movedItem] = reordered.splice(fromIndex, 1);
140 |       reordered.splice(dropIndex, 0, movedItem);
141 | 
142 |       onReorderPlaylist?.(reordered);
143 |       dragItemIndex.current = null;
144 |       setDragOverIndex(null);
145 |     },
146 |     [tracks, onReorderPlaylist, resolveOriginalIndex]
147 |   );
148 | 
149 |   return (
150 |     <section
151 |       className={`playlist-panel ${isDragOver ? "playlist-drag-over" : ""}`}
152 |       onDragOver={handleDragOverWindow}
153 |       onDragLeave={handleDragLeaveWindow}
154 |       onDrop={handleDropWindow}
155 |     >
156 |       <div className="panel-header">PLAYLIST</div>
157 |       {isDragOver && (
158 |         <div className="playlist-drop-indicator">
159 |           📁 Solte os arquivos para adicionar à playlist
160 |         </div>
161 |       )}
162 |       <div className="playlist-search-container">
163 |         <input
164 |           type="text"
165 |           className="playlist-search-input"
166 |           placeholder="Buscar música..."
167 |           value={searchQuery}
168 |           onChange={(e) => setSearchQuery(e.target.value)}
169 |           aria-label="Buscar música na playlist"
170 |         />
171 |         {searchQuery && (
172 |           <button
173 |             className="playlist-search-clear"
174 |             onClick={() => setSearchQuery("")}
175 |             title="Limpar busca"
176 |             aria-label="Limpar busca"
177 |           >
178 |             ✕
179 |           </button>
180 |         )}
181 |       </div>
182 |       {searchQuery && (
183 |         <div className="playlist-search-count">
184 |           {filteredTracks.length === 0
185 |             ? "Nenhuma música encontrada"
186 |             : `${filteredTracks.length} de ${tracks.length} música${tracks.length !== 1 ? "s" : ""}`}
187 |         </div>
188 |       )}
189 |       <ul className="playlist">
190 |         {tracks.length === 0 ? (
191 |           <li className="playlist-item playlist-empty">
192 |             Nenhuma música na playlist
193 |           </li>
194 |         ) : filteredTracks.length === 0 ? (
195 |           <li className="playlist-item playlist-empty">
196 |             Nenhuma música encontrada
197 |           </li>
198 |         ) : (
199 |           filteredTracks.map((track, filteredIndex) => (
200 |             <li
201 |               key={track.id}
202 |               className={`playlist-item ${
203 |                 track.id === currentTrackId ? "active" : ""
204 |               } ${dragOverIndex === filteredIndex ? "drag-over" : ""}`}
205 |               draggable
206 |               onClick={() => onSelectTrack(track)}
207 |               onDragStart={(e) => handleDragStart(e, filteredIndex)}
208 |               onDragEnd={handleDragEnd}
209 |               onDragOver={(e) => handleDragOver(e, filteredIndex)}
210 |               onDragLeave={handleDragLeave}
211 |               onDrop={(e) => handleDrop(e, filteredIndex)}
212 |               title={`${track.title}${track.artist ? ` — ${track.artist}` : ""}`}
213 |             >
214 |               <span className="playlist-item-drag-handle" title="Arrastar para reordenar">
215 |                 ⠿
216 |               </span>
217 |               <span className="playlist-item-icon">
218 |                 {track.id === currentTrackId && isPlaying ? "▶" : "🎵"}
219 |               </span>
220 |               <span className="playlist-item-title">{track.title}</span>
221 |               {track.artist && (
222 |                 <span className="playlist-item-artist">{track.artist}</span>
223 |               )}
224 |               <span className="playlist-item-duration">
225 |                 {formatDuration(track.duration)}
226 |               </span>
227 |             </li>
228 |           ))
229 |         )}
230 |       </ul>
231 |       <div className="panel-footer">
232 |         <span>{tracks.length} música{tracks.length !== 1 ? "s" : ""}</span>
233 |         <span>
234 |           {tracks.reduce((acc, t) => acc + t.duration, 0) > 0
235 |             ? formatDuration(tracks.reduce((acc, t) => acc + t.duration, 0))
236 |             : "—:—:—"}
237 |         </span>
238 |       </div>
239 |     </section>
240 |   );
241 | }
